// Strataflow Go (WASM) demo tenant.
// Contract: func Handle(w http.ResponseWriter, r *http.Request) in package main.
// Everything else (WASM adapter, bridges) is generated by the platform at build time.
//
// This demo intentionally avoids encoding/json: hand-built JSON keeps the wasm
// module small and the TinyGo build light enough for the platform's 256M build
// cgroup. Using encoding/json also works — the module just gets bigger.
package main

import (
	"net/http"
	"runtime"
	"strings"
)

// Handle is the whole platform contract — plain Go.
func Handle(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	switch {
	case r.URL.Path == "/" && r.Method == http.MethodGet:
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"service":"go-wasm-demo","status":"ok","runtime":"tinygo-wasm","goversion":"` + runtime.Version() + `"}`))

	case r.URL.Path == "/api/users" && r.Method == http.MethodPost:
		body := make([]byte, 0, 4096)
		buf := make([]byte, 2048)
		for {
			n, err := r.Body.Read(buf)
			if n > 0 {
				body = append(body, buf[:n]...)
				if len(body) > 64*1024 {
					w.WriteHeader(http.StatusBadRequest)
					_, _ = w.Write([]byte(`{"error":"invalid json"}`))
					return
				}
			}
			if err != nil {
				break
			}
		}
		name := jsonName(string(body))
		w.WriteHeader(http.StatusCreated)
		_, _ = w.Write([]byte(`{"id":42,"name":"` + jsonEscape(name) + `"}`))

	case r.URL.Path == "/env" && r.Method == http.MethodGet:
		// sfEnvGet is generated into this package by the platform; reads project env.
		greeting := sfEnvGet("GREETING")
		if greeting == "" {
			greeting = "(GREETING not set — add it in project env vars)"
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"greeting":"` + jsonEscape(greeting) + `"}`))

	case r.URL.Path == "/big":
		// Deliberate >1MB allocation: must trip the memory cap (trap -> honest 500)
		// on tier micro; passes on tiers default/max.
		sink := make([]byte, 2*1024*1024)
		sink[0] = 1
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"allocated":2097152}`))

	case r.URL.Path == "/loop":
		// Deliberate infinite loop: must be killed by the 10s wall-clock timeout.
		for {
		}

	default:
		w.WriteHeader(http.StatusNotFound)
		_, _ = w.Write([]byte(`{"error":"not found","path":"` + jsonEscape(r.URL.Path) + `"}`))
	}
}

// jsonName extracts a top-level "name":"value" from a tiny JSON object without
// pulling encoding/json into the module.
func jsonName(body string) string {
	i := strings.Index(body, `"name"`)
	if i < 0 {
		return ""
	}
	rest := body[i+len(`"name"`):]
	c := strings.Index(rest, `"`)
	if c < 0 || c+1 >= len(rest) {
		return ""
	}
	rest = rest[c+1:]
	o := strings.Index(rest, `"`)
	if o < 0 {
		return ""
	}
	return rest[:o]
}

// jsonEscape escapes the two characters that would break a JSON string.
func jsonEscape(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	return strings.ReplaceAll(s, `"`, `\"`)
}

func main() {}
